import { useState, useEffect, useMemo } from "react";
import { MapContainer, TileLayer, Popup, GeoJSON, useMapEvents, Polygon } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import { useNavigate } from "react-router-dom";
import "../styles/AdminDashboard.css";

const API_BASE = "http://localhost:8000";

function MapEvents({ drawingMode, currentPoints, setCurrentPoints }) {
    useMapEvents({
        click(e) {
            if (drawingMode) {
                const { lat, lng } = e.latlng;
                setCurrentPoints([...currentPoints, [lat, lng]]);
            }
        },
    });
    return null;
}

export default function AdminDashboard() {
    const navigate = useNavigate();
    const [activeTab, setActiveTab] = useState("territories");
    const [territories, setTerritories] = useState([]);
    const [allZones, setAllZones] = useState([]);
    
    const [selectedTerritoryId, setSelectedTerritoryId] = useState(null);
    const [showTerritoryForm, setShowTerritoryForm] = useState(false);
    const [newTerritoryName, setNewTerritoryName] = useState("");
    
    const [isDrawing, setIsDrawing] = useState(false);
    const [editingZoneId, setEditingZoneId] = useState(null);
    const [tempPoints, setTempPoints] = useState([]); 
    const [newZoneName, setNewZoneName] = useState("");

    useEffect(() => {
        refreshData();
    }, []);

    const refreshData = async () => {
        try {
            const [tRes, zRes] = await Promise.all([
                fetch(`${API_BASE}/territories`),
                fetch(`${API_BASE}/zones`)
            ]);
            if (tRes.ok) setTerritories(await tRes.json());
            if (zRes.ok) setAllZones(await zRes.json());
        } catch (e) { console.error("Lỗi tải dữ liệu:", e); }
    };

    // --- KHÔI PHỤC: Xử lý xóa phân vùng ---
    const handleDeleteTerritory = async (id) => {
        if (!window.confirm("Bạn có chắc chắn muốn xóa phân vùng này và toàn bộ dữ liệu liên quan?")) return;
        try {
            const res = await fetch(`${API_BASE}/territories/${id}`, { method: "DELETE" });
            if (res.ok) {
                if (selectedTerritoryId === id) setSelectedTerritoryId(null);
                refreshData();
            }
        } catch (e) { alert("Lỗi khi xóa phân vùng"); }
    };

    const handleCreateTerritory = async () => {
        if (!newTerritoryName) return;
        try {
            const res = await fetch(`${API_BASE}/territories`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ name: newTerritoryName, zone_ids: [] })
            });
            if (res.ok) {
                setNewTerritoryName("");
                setShowTerritoryForm(false);
                refreshData();
            }
        } catch (e) { alert("Lỗi tạo phân vùng"); }
    };

    // --- SỬA LỖI: Xử lý Vẽ & Liên kết Zone với Territory ---
    const saveDrawnZone = async () => {
        if (tempPoints.length < 3) return alert("Cần ít nhất 3 điểm");
        if (!newZoneName) return alert("Vui lòng nhập tên vùng");

        const coords = [...tempPoints, tempPoints[0]].map(p => [p[1], p[0]]); 
        const geometry = { type: "Polygon", coordinates: [coords] };

        try {
            if (editingZoneId) {
                // Cập nhật vị trí
                const res = await fetch(`${API_BASE}/zones/${editingZoneId}`, {
                    method: "PUT",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ name: newZoneName, geometry: geometry })
                });
                if (!res.ok) throw new Error("Lỗi cập nhật Zone");
            } else {
                // TẠO MỚI VÀ LIÊN KẾT
                // Tìm đoạn này trong saveDrawnZone
                const zoneRes = await fetch(`${API_BASE}/zones`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({
                        zone_code: `Z-${Date.now()}`,
                        name: newZoneName,
                        territory_id: Number(selectedTerritoryId), // SỬA TẠI ĐÂY
                        geometry: geometry,
                        center_lat: tempPoints[0][0],
                        center_lng: tempPoints[0][1],
                        num_customers: 0, num_orders: 0, revenue: 0
                    })
                });
                
                if (!zoneRes.ok) throw new Error("Không thể tạo Zone");
                const createdZone = await zoneRes.json();

                // Lấy phân vùng hiện tại
                const territory = territories.find(t => Number(t.id) === Number(selectedTerritoryId));
                if (!territory) throw new Error("Không tìm thấy phân vùng đang chọn");

                // Chuẩn bị mảng ID (ép kiểu số)
                // Trong hàm saveDrawnZone
                const currentIds = Array.isArray(territory.zone_ids) 
                    ? territory.zone_ids.map(id => Number(id)) 
                    : [];

                // Ép kiểu Number cho ID mới
                const updatedZoneIds = [...currentIds, Number(createdZone.id)];

                // Log ra để kiểm tra trước khi gửi
                console.log("Gửi danh sách ID mới:", updatedZoneIds);

                const updateRes = await fetch(`${API_BASE}/territories/${selectedTerritoryId}`, {
                    method: "PUT",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ 
                        zone_ids: updatedZoneIds // Phải là mảng số: [1, 2, 3]
                    })
                });

                if (!updateRes.ok) {
                    const errorData = await updateRes.json();
                    console.error("Backend Error:", errorData);
                    throw new Error("Không thể liên kết Zone vào Phân vùng");
                }
            }
            
            alert("Lưu và liên kết thành công!");
            setIsDrawing(false);
            setTempPoints([]);
            setEditingZoneId(null);
            setNewZoneName("");
            await refreshData(); 
        } catch (e) { 
            alert("Lỗi: " + e.message); 
        }
    };

    const deleteZone = async (zoneId) => {
        if (!window.confirm("Xóa vùng này?")) return;
        try {
            await fetch(`${API_BASE}/zones/${zoneId}`, { method: "DELETE" });
            refreshData();
        } catch (e) { alert("Lỗi khi xóa zone"); }
    };

    // --- SỬA LỖI: Logic lọc Zones (ép kiểu ID để so khớp chính xác) ---
    const activeZones = useMemo(() => {
        if (!selectedTerritoryId) return [];
        
        // Lọc tất cả các zones có territory_id trùng với territory đang chọn
        return allZones.filter(z => 
            Number(z.territory_id) === Number(selectedTerritoryId)
        );
    }, [selectedTerritoryId, allZones]);

    const getZoneColor = (index) => {
        const colors = ['#e74c3c', '#3498db', '#2ecc71', '#f1c40f', '#9b59b6', '#1abc9c', '#e67e22'];
        return colors[index % colors.length];
    };

    return (
        <div className="admin-container">
            <aside className="admin-sidebar">
                <div className="logo">🚀 Territory System</div>
                <nav className="main-nav">
                    <button className={activeTab === "territories" ? "active" : ""} onClick={() => setActiveTab("territories")}>🗺️ Quản lý Phân vùng</button>
                    <button className={activeTab === "sales" ? "active" : ""} onClick={() => setActiveTab("sales")}>👥 Sales</button>
                </nav>
                <button className="logout-btn" onClick={() => navigate("/")}>Đăng xuất</button>
            </aside>

            <main className="admin-main">
                <div className="tab-content">
                    <div className="zone-mgr-header">
                        <h2>Thiết kế Phân vùng</h2>
                        <button className="btn-primary" onClick={() => setShowTerritoryForm(true)}>➕ Tạo Phân vùng mới</button>
                    </div>

                    <div className="zone-mgr-layout">
                        <div className="district-list">
                            <h4>Phân vùng mục tiêu</h4>
                            {territories.map(t => (
                                <div 
                                    key={t.id} 
                                    className={`dist-item-card ${selectedTerritoryId === t.id ? "selected-active" : ""}`}
                                    onClick={() => setSelectedTerritoryId(t.id)}
                                >
                                    <div className="dist-info">
                                        <span className="icon">{selectedTerritoryId === t.id ? "🎯" : "📍"}</span>
                                        <span className="name">{t.name}</span>
                                    </div>
                                    <div className="dist-actions">
                                        <span className="count">{t.zone_ids?.length || 0}</span>
                                        {/* KHÔI PHỤC: Nút xóa phân vùng */}
                                        <button className="btn-icon-del" onClick={(e) => {
                                            e.stopPropagation(); // Ngăn sự kiện click vào card
                                            handleDeleteTerritory(t.id);
                                        }}>🗑️</button>
                                    </div>
                                </div>
                            ))}
                        </div>

                        <div className="zone-display">
                            <div className="map-toolbar">
                                {isDrawing ? (
                                    <div className="drawing-controls">
                                        <input type="text" placeholder="Tên vùng..." value={newZoneName} onChange={e => setNewZoneName(e.target.value)} />
                                        <button className="btn-success" onClick={saveDrawnZone}>💾 Lưu</button>
                                        <button className="btn-draw" onClick={() => setTempPoints(prev => prev.slice(0, -1))}>↩️ Hoàn tác</button>
                                        <button className="btn-reject" onClick={() => { setIsDrawing(false); setTempPoints([]); }}>🚫 Hủy</button>
                                    </div>
                                ) : (
                                    <div className="toolbar-info">
                                        {selectedTerritoryId ? (
                                            <button className="btn-draw" onClick={() => {
                                                setIsDrawing(true);
                                                setEditingZoneId(null);
                                                setTempPoints([]);
                                                setNewZoneName("");
                                            }}>✏️ Vẽ vùng mới cho "{territories.find(t=>t.id===selectedTerritoryId)?.name}"</button>
                                        ) : (
                                            <span className="hint-text">👈 Chọn một phân vùng để quản lý Zones</span>
                                        )}
                                    </div>
                                )}
                            </div>

                            <div className="map-box">
                                <MapContainer center={[21.0285, 105.8542]} zoom={13} style={{ height: '400px', width: '100%' }}>
                                    <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
                                    <MapEvents drawingMode={isDrawing} currentPoints={tempPoints} setCurrentPoints={setTempPoints} />
                                    {tempPoints.length > 0 && <Polygon positions={tempPoints} pathOptions={{ color: 'orange' }} />}

                                    {activeZones.map((z, idx) => (
                                        <GeoJSON 
                                            key={`zone-${z.id}-${idx}`} 
                                            data={z.geometry} 
                                            style={{ color: getZoneColor(idx), fillOpacity: 0.5 }}
                                        >
                                            <Popup><strong>{z.name}</strong></Popup>
                                        </GeoJSON>
                                    ))}
                                </MapContainer>
                            </div>

                            <div className="zone-details-list">
                                <h3>Zones hiển thị: {activeZones.length} vùng</h3>
                                {activeZones.length > 0 ? (
                                    <div className="zone-table-container">
                                        <table className="zone-table">
                                            <thead>
                                                <tr>
                                                    <th>Màu</th>
                                                    <th>Tên Zone</th>
                                                    <th>Hành động</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {activeZones.map((z, idx) => (
                                                    <tr key={z.id}>
                                                        <td><div className="color-box" style={{backgroundColor: getZoneColor(idx)}}></div></td>
                                                        <td>{z.name}</td>
                                                        <td>
                                                            <button className="btn-small" onClick={() => {
                                                                setEditingZoneId(z.id);
                                                                setNewZoneName(z.name);
                                                                setIsDrawing(true);
                                                                setTempPoints([]);
                                                            }}>📍 Vẽ lại</button>
                                                            <button className="btn-small-del" onClick={() => deleteZone(z.id)}>🗑️</button>
                                                        </td>
                                                    </tr>
                                                ))}
                                            </tbody>
                                        </table>
                                    </div>
                                ) : (
                                    <p className="empty-msg">Chưa có vùng nào được liên kết.</p>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </main>

            {showTerritoryForm && (
                <div className="modal-overlay">
                    <div className="modal-content">
                        <h3>Tạo Phân vùng</h3>
                        <input type="text" placeholder="Tên phân vùng..." value={newTerritoryName} onChange={e => setNewTerritoryName(e.target.value)} />
                        <div className="modal-btns">
                            <button onClick={handleCreateTerritory} className="btn-success">Lưu</button>
                            <button onClick={() => setShowTerritoryForm(false)}>Hủy</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}
